    public void Dispose()=>connection.Dispose();
    private DbCommand Command(string sql,params object?[] values){var cmd=connection.CreateCommand();cmd.CommandText=sql;cmd.CommandTimeout=15;for(var i=0;i<values.Length;i++){var p=cmd.CreateParameter();p.ParameterName="p"+i;p.Value=values[i]??DBNull.Value;cmd.Parameters.Add(p);}return cmd;}
    private static void Identity(string tenant,string subject){if(!Regex.IsMatch(tenant,"^(shared|[a-f0-9]{64})$")||!Regex.IsMatch(subject,"^[a-f0-9]{64}$"))throw new ProcessingException("INVALID_GOVERNANCE_IDENTITY");}
    private static void ProjectId(string project){if(!Regex.IsMatch(project,"^[a-zA-Z0-9][a-zA-Z0-9_-]{0,79}$"))throw new ProcessingException("INVALID_GOVERNANCE_PROJECT");}
    public JsonArray Events(string tenant,string subject){Identity(tenant,subject);using var cmd=Command("SELECT sequence,project,event,hash FROM governance_events WHERE tenant=@p0 AND subject=@p1 ORDER BY sequence",tenant,subject);using var reader=cmd.ExecuteReader();var result=new JsonArray();var previous=new string('0',64);
        while(reader.Read()){
            var raw=reader.GetString(2);var value=Data.ParseStrict(Encoding.UTF8.GetBytes(raw)) as JsonObject??throw new ProcessingException("GOVERNANCE_AUDIT_INTEGRITY_FAILED");var hash=reader.GetString(3);var sequence=result.Count+1;
            if(sequence>256||reader.GetInt32(0)!=sequence||value["sequence"]?.GetValue<int>()!=sequence||value["project"]?.GetValue<string>()!=reader.GetString(1)||value["tenant"]?.GetValue<string>()!=tenant||value["subject"]?.GetValue<string>()!=subject||value["previous_hash"]?.GetValue<string>()!=previous||!CryptographicOperations.FixedTimeEquals(Encoding.ASCII.GetBytes(Data.Hash(raw)),Encoding.ASCII.GetBytes(hash)))throw new ProcessingException("GOVERNANCE_AUDIT_INTEGRITY_FAILED");
            value["hash"]=hash;result.Add(value);previous=hash;
        }return result;
    }
    private void Begin(string scope){using var cmd=Command(postgres?"BEGIN":"BEGIN IMMEDIATE");cmd.ExecuteNonQuery();if(postgres){using var guard=Command("SELECT pg_advisory_xact_lock(hashtextextended(@p0,0))","openehr-governance:"+scope);guard.ExecuteNonQuery();}}
    private void Finish(bool commit){using var cmd=Command(commit?"COMMIT":"ROLLBACK");cmd.ExecuteNonQuery();}
    public JsonObject Append(string tenant,string subject,int expected,JsonObject input){Identity(tenant,subject);var project=Data.Required(input,"project");ProjectId(project);if(expected<0||expected>=256||input.Any(p=>new[]{"tenant","subject","sequence","timestamp","hash","previous_hash"}.Contains(p.Key)))throw new ProcessingException("INVALID_GOVERNANCE_EVENT");Begin(tenant+":"+subject);
        try{var history=Events(tenant,subject);if(history.Count!=expected)throw new ProcessingException("GOVERNANCE_REVISION_CONFLICT");if(history.Count>0&&history[0]?["project"]?.GetValue<string>()!=project)throw new ProcessingException("GOVERNANCE_SUBJECT_IDENTITY_CONFLICT");
            var value=new JsonObject{["tenant"]=tenant,["subject"]=subject,["sequence"]=expected+1,["timestamp"]=DateTimeOffset.UtcNow.ToString("O"),["previous_hash"]=expected==0?new string('0',64):history[^1]!["hash"]!.DeepClone()};foreach(var(k,v)in input)value[k]=v?.DeepClone();var raw=value.ToJsonString();if(Encoding.UTF8.GetByteCount(raw)>65536)throw new ProcessingException("GOVERNANCE_EVENT_TOO_LARGE");var hash=Data.Hash(raw);using var cmd=Command("INSERT INTO governance_events(tenant,subject,sequence,project,event,hash) VALUES(@p0,@p1,@p2,@p3,@p4,@p5)",tenant,subject,expected+1,project,raw,hash);cmd.ExecuteNonQuery();Finish(true);value["hash"]=hash;return value;
        }catch{Finish(false);throw;}
    }
    public JsonArray Subjects(string tenant,string project,int count=25,int offset=0,string? firstType=null){ProjectId(project);if(count is <1 or >100||offset is <0 or >10000)throw new ProcessingException("INVALID_GOVERNANCE_PAGE");var filter=firstType is null?"":postgres?" AND CAST(first.event AS jsonb)->>'type'=@p4":" AND json_extract(first.event,'$.type')=@p4";
        using var cmd=Command("SELECT e.subject FROM governance_events e JOIN governance_events first ON first.tenant=e.tenant AND first.subject=e.subject AND first.sequence=1 WHERE e.tenant=@p0 AND e.project=@p1"+filter+" GROUP BY e.subject ORDER BY e.subject LIMIT @p2 OFFSET @p3",firstType is null?[tenant,project,count,offset]:[tenant,project,count,offset,firstType]);var ids=new List<string>();using(var reader=cmd.ExecuteReader())while(reader.Read())ids.Add(reader.GetString(0));var result=new JsonArray();foreach(var id in ids){var events=Events(tenant,id);result.Add(new JsonObject{["subject"]=id,["sequence"]=events.Count,["first"]=events[0]!.DeepClone(),["latest"]=events[^1]!.DeepClone()});}return result;
    }
    public void ConsumeNonce(string nonce,long expires){var now=DateTimeOffset.UtcNow.ToUnixTimeSeconds();if(!Regex.IsMatch(nonce,"^[a-f0-9]{64}$")||expires<now||expires>now+120)throw new ProcessingException("INVALID_GOVERNANCE_ASSERTION");Begin("governance-nonces");try{using(var clean=Command("DELETE FROM governance_nonces WHERE expires<@p0",now-120))clean.ExecuteNonQuery();using(var size=Command("SELECT COUNT(*) FROM governance_nonces"))if(Convert.ToInt32(size.ExecuteScalar(),System.Globalization.CultureInfo.InvariantCulture)>=10000)throw new ProcessingException("GOVERNANCE_ASSERTION_LIMIT_EXCEEDED");using(var insert=Command("INSERT INTO governance_nonces(nonce,expires) VALUES(@p0,@p1) ON CONFLICT(nonce) DO NOTHING",nonce,expires))if(insert.ExecuteNonQuery()!=1)throw new ProcessingException("GOVERNANCE_ASSERTION_REPLAYED");Finish(true);}catch{Finish(false);throw;}}
